(function(){'use strict';const C=window.FastooleeImageCore,root=document.querySelector('[data-dpi-checker]');if(!C||!root)return;const file=root.querySelector('[data-file]'),drop=root.querySelector('[data-drop]'),result=root.querySelector('[data-result]'),err=root.querySelector('[data-error]');let source=null;const showError=t=>{err.textContent=t||'';err.hidden=!t;};async function inspect(f){showError('');if(source)C.releaseImage(source);try{source=await C.fileToImage(f);const dpiX=source.dpi.x,dpiY=source.dpi.y||dpiX;const print=dpiX?C.pxToUnits(source.width,dpiX):null,printY=dpiY?C.pxToUnits(source.height,dpiY):null;result.hidden=false;result.innerHTML=`<div class="metric-grid"><article><small>Image size</small><strong>${source.width} × ${source.height} px</strong></article><article><small>DPI</small><strong>${dpiX?`${dpiX}${dpiY&&dpiY!==dpiX?` × ${dpiY}`:''}`:'Not embedded'}</strong></article><article><small>File size</small><strong>${C.humanBytes(source.size)}</strong></article><article><small>Format</small><strong>${source.type.replace('image/','').toUpperCase()}</strong></article><article><small>Estimated print size</small><strong>${print?`${print.in.toFixed(2)} × ${printY.in.toFixed(2)} in`:'Needs DPI metadata'}</strong></article><article><small>Centimeters</small><strong>${print?`${print.cm.toFixed(1)} × ${printY.cm.toFixed(1)} cm`:'—'}</strong></article></div>${!dpiX?'<p class="tool-note warn-note">This image has no readable DPI metadata. Pixel dimensions are still exact; use the DPI Changer if you need a specific embedded DPI.</p>':''}`;}catch(e){showError(e.message||'Could not inspect this image.');}}
if(file)file.addEventListener('change',()=>file.files[0]&&inspect(file.files[0]));if(drop){['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('is-drag')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('is-drag')}));drop.addEventListener('drop',e=>{const f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f)inspect(f);});}})();
